@Component("appointment-handler")
@ProcessingGroup("appointment-processing-group")
public class AppointmentEventHandler {
	
	// core constructor
	AppointmentEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateAppointmentEvent
     */
    @EventHandler
    public void handle( CreateAppointmentEvent event) {
        entityManager.persist(new Appointment(event.getAppointmentId(), event.getAppointmentDate(), event.getReason(), event.getPatient(), event.getClinician(), event.getFacility(), event.getEncounter(), event.getStatus(), event.getPriority()));
    }

    /*
     * @param	event UpdateAppointmentEvent
     */
    @EventHandler
    public Appointment handle( UpdateAppointmentEvent event) {
    	entityManager.merge(new Appointment(event.getAppointmentId(), event.getAppointmentDate(), event.getReason(), event.getPatient(), event.getClinician(), event.getFacility(), event.getEncounter(), event.getStatus(), event.getPriority()));
    }
    
    /*
     * @param	event DeleteAppointmentEvent
     */
    @EventHandler
    public void on( DeleteAppointmentEvent event) {
    	Appointment entity = new Appointment();
   
    	// ------------------------------------------
    	// apply the AppointmentId
    	// ------------------------------------------
    	entity.setAppointmentId( event.getAppointmentId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final AppointmentRepository appointmentEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(AppointmentEventHandler.class.getName());

}
